msg.statusCode = 200;
msg.payload = { ok: true, service: "smart-parking-node-red", timestamp: new Date().toISOString() };
return msg;

const body = msg.payload || {};
const gate = String(body.gate_id || "").toLowerCase();
const uid = String(body.uid || "").replace(/\s+/g, "").toUpperCase();
if (!["entry", "exit"].includes(gate) || !/^[A-F0-9]{4,32}$/.test(uid)) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: "gate_id must be entry or exit and uid must contain 4-32 hexadecimal characters" };
    return [null, msg];
}
msg.scan = { gate_id: gate, uid: uid, timestamp: new Date().toISOString() };
msg.topic = "INSERT INTO access_events (gate_id, card_uid, event_type, created_at) VALUES (?, ?, 'rfid_scan', ?)";
msg.payload = [gate, uid, msg.scan.timestamp];
return [msg, null];

msg.statusCode = 201;
msg.payload = { ok: true, message: "RFID scan recorded", gate_id: msg.scan.gate_id, uid: msg.scan.uid, timestamp: msg.scan.timestamp, note: "A scan event does not confirm that a vehicle physically passed the gate." };
return msg;

msg.statusCode = 500;
msg.payload = { ok: false, error: "Database operation failed" };
return msg;
